import java.util.*;

class Solution {
    public int maxItems(int[][] crates, int capacity) {
        int[][] c = crates.clone();
        Arrays.sort(c, (a, b) -> Integer.compare(b[1], a[1]));   // richest crates first
        int total = 0;
        for (int[] t : c) {
            if (capacity == 0) break;
            int take = Math.min(t[0], capacity);
            total += take * t[1];
            capacity -= take;
        }
        return total;
    }
}

