class Solution:
    def maxItems(self, crates: List[List[int]], capacity: int) -> int:
        total = 0
        for c, per in sorted(crates, key=lambda x: -x[1]):
            take = min(c, capacity)
            total += take * per; capacity -= take
            if capacity == 0: break
        return total

