function maxItems(crates, capacity) {
  const a = crates.slice().sort((p, q) => q[1] - p[1]);
  let total = 0;
  for (const [c, per] of a) { const t = Math.min(c, capacity); total += t * per; capacity -= t; if (!capacity) break; }
  return total;
}
